use vstd::prelude::*;

verus! {

    /// flipud takes a vector of 32‐bit floats and returns a new vector
    /// containing the same elements in reverse order.
    pub fn flipud(m: Vec<f32>) -> Vec<f32>
        ensures |res: &Vec<f32>|
            // The result has the same length as the input
            res.len() == m.len()
            // And for every valid index i, res[i] == m[n-1-i]
            && forall |i: usize| (i < m.len()) ==>
                 res[i] == m[m.len() - 1 - i]
    {
        // We build the reversed vector element by element.
        let mut res = Vec::with_capacity(m.len());
        let mut i: usize = 0;

        // Loop until we've processed all positions.
        while i < m.len() {
            // Invariant: i never exceeds m.len()
            invariant i <= m.len();
            // Invariant: res.len() == number of elements pushed so far
            invariant res.len() == i;
            // Invariant: for every j < i, we have already reversed that element
            invariant forall |j: usize|
                j < i ==>
                res[j] == m[m.len() - 1 - j];
            // We make progress by incrementing i
            decreases m.len() - i;
            {
                // Push the “mirrored” element
                let x = m[m.len() - 1 - i];
                res.push(x);
                i += 1;
            }
        }

        res
    }

}